<title>找出长难句主干谓语动词的三步骤</title>
<script>
window.MathJax = { tex: { inlineMath: [['$', '$']], displayMath: [['$$', '$$']] } };
</script>
<script src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js" async></script>
<style>
  body {
    font-family: "Microsoft YaHei", "SimSun", Arial, sans-serif;
    font-size: 13px;
    color: #222;
    max-width: 800px;
    margin: 20px auto;
    padding: 20px 30px;
    position: relative;
    line-height: 1.6;
  }
  .title-line {
    font-weight: bold;
