    margin-bottom: 10px;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #3f7fbf;
    margin-top: 4px;
  }
  th {
    background: #e9f1fb;
    border: 1px solid #3f7fbf;
    padding: 6px 8px;
    font-size: 13px;
    color: #1f4e79;
  }
  th:first-child { width: 15%; }
  td {
    border: 1px solid #3f7fbf;
    padding: 8px 10px;
    vertical-align: top;
    font-size: 12.5px;
  }
  .label-cell {
    text-align: center;
    vertical-align: middle;
    font-weight: bold;
    color: #1f1f1f;
  }
  .label-hl {
    background: #ffe08a;
