  }
  .example {
    margin-top: 4px;
  }
  .main-clause {
    color: #1f4e79;
    font-weight: bold;
    border-bottom: 2px solid #1f4e79;
  }
  .sub-clause {
    color: #d98c00;
    border-bottom: 1px dashed #d98c00;
  }
  .strike {
    color: #d98c00;
    text-decoration: line-through;
    border-bottom: 1px dashed #d98c00;
  }
  .plain-underline {
    border-bottom: 1px solid #999;
  }
  .page-num {
    text-align: center;
    margin-top: 20px;
    font-size: 12px;
    color: #444;
  }
